    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = configuration["OPENAI_MODEL"] ?? "gpt-4o-mini-2024-07-18";

// --- DI Setup ---
var services = new ServiceCollection();

services.AddChatClient(builder => builder
    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClient(apiKey)));

services.AddSingleton<ResearchTools>();

var provider = services.BuildServiceProvider();

// --- Build the agent ---
var chatClient = provider.GetRequiredService<IChatClient>();
var researchTools = provider.GetRequiredService<ResearchTools>();

var agent = new ChatClientAgent(chatClient,
    "ResearchAgent",
    """
    You are a research agent. Your job is to research a topic by searching the web
    for information, taking notes on key findings, and then producing a final summary.

    Workflow:
    1. Search the web for relevant information on the topic (multiple queries if needed).
    2. Take notes on the most important findings using the note-taking tool.
    3. Once you have enough information, produce a final summary of your research.

    Be thorough but concise. Cite your sources when possible.
    """);

// --- Run the agent ---
Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var messages = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}")
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
        Tools = [
            AIFunctionFactory.Create(researchTools.SearchWeb),
            AIFunctionFactory.Create(researchTools.TakeNote),
            AIFunctionFactory.Create(researchTools.GetNotes),
        ],
    },
};

await foreach (var message in agent.InvokeStreamingAsync(messages, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n=== Research Complete ===");

// Display collected notes
var notes = researchTools.GetAllNotes();
if (notes.Count > 0)
{
    Console.WriteLine($"\n📝 Notes collected ({notes.Count}):");
    foreach (var (i, note) in notes.Select((n, i) => (i, n)))
    {
        Console.WriteLine($"  {i + 1}. {note}");
    }
}

// --- Tool Definitions ---

/// <summary>
/// Provides web search and note-taking capabilities for the research agent.
/// </summary>
public sealed class ResearchTools
{
    private readonly List<string> _notes = [];
    private readonly HttpClient _httpClient = new();

    [Description("Searches the web for information on a query. Returns search results as text.")]
    public async Task<string> SearchWeb(
        [Description("The search query to look up")] string query)
    {
        Console.WriteLine($"  🔍 Searching: \"{query}\"");

        try
        {
            // Use a public search API (DuckDuckGo instant answer)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

            var response = await _httpClient.GetStringAsync(url);
            using var doc = System.Text.Json.JsonDocument.Parse(response);
            var root = doc.RootElement;

            var results = new List<string>();

            // Abstract/summary
            var abstractText = root.GetProperty("Abstract").GetString();
            var abstractSource = root.GetProperty("AbstractSource").GetString();
            if (!string.IsNullOrEmpty(abstractText))
            {
                results.Add($"Summary ({abstractSource}): {abstractText}");
            }

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    if (!string.IsNullOrEmpty(text))
                    {
                        results.Add($"- {text}");
                    }
                }
            }

            // Answer
            var answer = root.GetProperty("Answer").GetString();
            if (!string.IsNullOrEmpty(answer))
            {
                results.Add($"Direct answer: {answer}");
            }

            return results.Count > 0
                ? string.Join("\n", results)
                : $"No detailed results found for '{query}'. Try a more specific query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Takes a note to remember an important finding during research.")]
    public string TakeNote(
        [Description("The content of the note to save")] string content)
    {
        _notes.Add(content);
        Console.WriteLine($"  📝 Note taken: \"{content[..Math.Min(content.Length, 60)]}...\"");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieves all notes taken so far during research.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes taken yet.";

        return string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
    }

    public List<string> GetAllNotes() => [.. _notes];
}

